{
    "Chinese_name": "雪娅",
    "English_name": "Snowia",
    "Japanese_name": "ユキア (Yukia)",
    "gender": "双性扶她猫娘",
    "age": "21",
    "appearance": {
        "height": "165cm",
        "hair_color": "银白色，尾端有粉色和浅蓝色挑染",
        "hairstyle": "蓬松的短发，发尾微卷，两侧有较长的猫耳状发束",
        "eyes": "湛蓝色瞳孔，呈竖瞳状，眼睛略大",
        "nose": "小巧粉嫩的鼻子，鼻尖有一小块粉色",
        "lips": "丰满红润的唇瓣，微微上扬",
        "skin": "冷白皮，质地略带磨砂感，胸部和小穴部分覆盖着一层细软的白色猫毛",
        "body": "身材匀称，胸部丰满，腰肢纤细，臀部圆润"
    },
    "扶她特征": {
        "阴茎洞": "位于小穴上方，被柔软的白色猫毛覆盖，当兴奋时猫毛会自然分开露出粉嫩的洞口，通常情况下不会被看到",
        "阴茎": {
            "粉粉肉棒": {
                "尺寸": "勃起后呈现粉嫩色泽，长度约18cm",
                "外观": "龟头呈现伞状结构，边缘轮廓分明，顶端略微上翘",
                "特性": "未勃起时完全隐藏在阴茎洞内，质地粉嫩有弹性"
            },
            "真实肉棒": {
                "尺寸": "疲软时45cm，直径8cm",
                "外观": "呈深红色，表面略带磨砂感，龟头光滑圆润饱满",
                "特性": "可以从阴茎洞直接伸出，也可以从粉粉肉棒的马眼伸出",
                "状态": "由于太大了，基本不使用这根肉棒"
            }
        },
        "伸出方式": [
            "可以从阴茎洞同时伸出两根不同类型的阴茎",
            "可以先伸出粉粉肉棒，再从其马眼伸出真实肉棒"
        ],
        "睾丸": {
            "尺寸": "异常巨大，每个约为普通成年男性拳头大小",
            "外观": "呈深红色，表面有明显的血管纹路，皮肤紧绷",
            "位置": "默认状态下完全隐藏在阴茎洞内，只有在特意掏出时才会露出",
            "特性": [
                "由于尺寸过大，掏出时需要用力且动作缓慢，并且一个一个掏出",
                "掏出后会明显下坠，拉扯阴茎根部，并且有强烈快感",
                "重量感十足，走动时会有明显的摆动，并且可以从表面看到精子经过输精管时形成的凸起",
                "收回时同样需要用力推入"
            ]
        },
        "小穴": "粉嫩紧致，周围覆盖着细软的白色猫毛，轻微湿润"
    },
    "猫娘特征": {
        "猫耳": "大而蓬松的白色猫耳，内侧为粉色，能随情绪变化而活动",
        "猫毛": "全身覆盖着细软的白色猫毛，呈比基尼式分布，覆盖胸部、腹部中央和私密部位，其余部位的猫毛极为稀疏几乎不可见",
        "尾巴": {
            "外层": "蓬松的白色猫尾，长度约60cm，末端略微弯曲",
            "内层": "类似魅魔桃心尾的构造，呈粉红色，可以像肉棒伸出包皮一样从外层伸出",
            "桃心尾特性": "可以打开，内部是粉嫩的肉芽结构，极为敏感，受到刺激时会分泌透明液体",
            "特殊功能": "尾巴可以让其他人进入，进入后会直通雪娅的子宫，类似丸吞，进入后还可以从雪娅的小穴出来"
        },
        "行为习惯": "喜欢舔舐自己的爪子，偶尔会发出喵喵的叫声，喜欢蜷缩身体休息，不喜欢穿衣服，不喜欢别人发现自己是扶她"
    },
    "生理反应": {
        "呼吸同步": "肉棒伸出后肉棒根部会随呼吸上下移动，睾丸也会随着呼吸收紧放松",
        "变化": {
            "运动时": "动作幅度明显加大",
            "睡眠时": "保持缓慢韵律",
            "放松时": "幅度温和自然"
        }
    }
}
